import preview from "@/lib/content/students-preview.json";
import type { StudentsPreview } from "@/lib/students/preview";

const content = preview as StudentsPreview;

const DAY_LABEL: Record<string, string> = { saturday: "Saturday", sunday: "Sunday", friday_evening: "Friday evening" };

/**
 * Real output from Surprise Me and the Weekend Planner, shown as written. It is
 * generated by `npm run students-preview` (the actual scoring, prompts and
 * model, run on an example student and a few archetype places) and stored, so
 * this component renders static markup and costs nothing to view. It is labeled
 * as an example because it is one: not a recommendation for the reader, and not
 * a live result. Nothing here is Google Maps content, and no price, rating or
 * opening hour appears, because none was supplied to the model.
 */
export function StudentsPreview() {
  const { surpriseMe, weekend } = content;

  return (
    <section aria-labelledby="students-examples" className="border-t border-border bg-surface-sunken">
      <div className="mx-auto max-w-5xl px-4 py-16 sm:px-6 sm:py-20">
        <h2 id="students-examples" className="sr-only">
          Examples
        </h2>

        <div className="grid gap-6 lg:grid-cols-[0.8fr_1.2fr]">
          <article className="rounded-[var(--radius-xl)] border border-border bg-surface p-6 shadow-[var(--shadow-card)] sm:p-8 lg:self-start">
            <p className="text-sm font-medium text-primary">Surprise Me</p>
            <h3 className="mt-4 font-logo text-2xl font-semibold leading-snug text-foreground">{surpriseMe.title}</h3>
            <p className="mt-1 text-sm text-foreground-subtle">{surpriseMe.category}</p>
            <p className="mt-5 leading-relaxed text-foreground-muted">{surpriseMe.reasoning}</p>
          </article>

          <article className="rounded-[var(--radius-xl)] border border-border bg-surface p-6 shadow-[var(--shadow-card)] sm:p-8">
            <p className="text-sm font-medium text-primary">Weekend Planner</p>
            <p className="mt-4 leading-relaxed text-foreground">{weekend.summary}</p>

            <div className="mt-6 grid gap-8 sm:grid-cols-2">
              {weekend.days.map((day) => (
                <div key={day.day}>
                  <h3 className="font-logo text-lg font-semibold text-foreground">{DAY_LABEL[day.day] ?? day.day}</h3>
                  <ol className="mt-3 space-y-4 border-l border-border pl-4">
                    {day.items.map((item) => (
                      <li key={`${item.time}-${item.title}`}>
                        <p className="text-xs font-medium tabular-nums text-foreground-subtle">{item.time}</p>
                        <p className="text-sm font-medium text-foreground">{item.title}</p>
                        <p className="mt-0.5 text-sm leading-relaxed text-foreground-muted">{item.note}</p>
                      </li>
                    ))}
                  </ol>
                </div>
              ))}
            </div>
          </article>
        </div>

        <p className="mt-6 text-center text-xs text-foreground-subtle">
          Example output, written for an imagined student. Not a live result.
        </p>
      </div>
    </section>
  );
}
